import fnmatch

def runner_for(path):
    name = path.rsplit('/', 1)[-1]
    if not name.endswith('.java'):
        return None
    name = name[:-5]
    if any(fnmatch.fnmatchcase(name, p) for p in ('IT*', '*IT', '*ITCase')):
        return 'failsafe'
    if any(fnmatch.fnmatchcase(name, p) for p in ('Test*', '*Test', '*Tests', '*TestCase')):
        return 'surefire'
    return None

def _key(v):
    snapshot = v.endswith('-SNAPSHOT')
    core = v[:-9] if snapshot else v
    parts = [int(p) for p in core.split('.')]
    while len(parts) < 3:
        parts.append(0)
    return (parts, 0 if snapshot else 1)

def newer(a, b):
    return b if _key(b) > _key(a) else a
